API Gateway & BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway & BFF") {
    Component(RequestRouter, "Request Router", "Node.js / Express", "Routes incoming storefront requests to appropriate backend microservices.")
    Component(RequestAggregator, "Request Aggregator", "Node.js", "Aggregates responses from multiple microservices to optimize client payloads.")
    Component(RateLimiterSecurityFilter, "Rate Limiter & Security Filter", "AWS WAF / API Gateway Native", "Enforces rate limiting and mitigates OWASP Top-10 vulnerabilities at the edge.")
    Component(SessionManager, "Session Manager", "Redis Client", "Interacts with Amazon ElastiCache to query and manage user session states.")
}

Rel(RequestRouter, RequestAggregator, "Forwards routed requests for aggregation")
Rel(RequestRouter, SessionManager, "Validates session state")
Rel(RateLimiterSecurityFilter, RequestRouter, "Passes sanitized and validated requests")

@enduml

Amazon ElastiCache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_elasticache, "Amazon ElastiCache") {
    Component(Session_State_Manager, "Session State Manager", "Redis In-Memory Data Store", "Manages user session state and user metadata for fast retrieval across the BFF and API Gateway.")
    Component(Catalog_Cache_Manager, "Catalog Cache Manager", "Redis In-Memory Data Store utilizing Cache-Aside pattern, LRU eviction, and Lazy Freeing", "Caches frequently accessed book catalog data to reduce read load on Amazon Aurora/RDS and ensure low-latency responses.")
}

Rel(Session_State_Manager, Catalog_Cache_Manager, "Shares memory resources and caching eviction policies within the ElastiCache cluster.", "Redis Protocol")

@enduml

AWS SQS/SNS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_sqs_sns, "AWS SQS/SNS") {
    Component(Amazon_SNS_Topics, "Amazon SNS Topics", "AWS SNS", "Publishes asynchronous events and broadcasts messages to multiple subscribers.")
    Component(Amazon_SQS_Queues, "Amazon SQS Queues", "AWS SQS", "Buffers and manages queues for asynchronous task processing across microservices.")
    Component(Dead_Letter_Queues, "Dead Letter Queues", "AWS SQS DLQ", "Captures and stores failed or poisoned messages for troubleshooting and reprocessing.")
}

Rel(Amazon_SNS_Topics, Amazon_SQS_Queues, "Fans out messages to queues", "HTTPS")
Rel(Amazon_SQS_Queues, Dead_Letter_Queues, "Forwards failed messages after max retry attempts", "HTTPS")
@enduml
